async function navigationOpen(req,message){
  const f=fold(message),loc=currentLocale(req);
  const routes=[
    {keys:['inicio','home'],target:'home',es:'Inicio',en:'Home'},
    {keys:['programa','schedule'],target:'schedule',es:'Programa',en:'Schedule'},
    {keys:['iglesia','noticias','church','news','boletin','bulletin','anuncios','announcements'],target:'church',es:'Iglesia / Noticias',en:'Church / News'},
    {keys:['evento','eventos','event','events'],target:'events',es:'Eventos',en:'Events'},
    {keys:['tarea','tareas','task','tasks'],target:'tasks',es:'Tareas',en:'Tasks'},
    {keys:['peticion','peticiones','oracion','prayer'],target:'petitions',es:'Peticiones',en:'Prayer Requests'},
    {keys:['perfil','profile'],target:'profile',es:'Perfil',en:'Profile'},
    {keys:['cuidado','ninos','children','nursery','toddlers'],target:'children',es:'Cuidado de Niños',en:'Children Care'},
    {keys:['chat hub','chat'],target:'chat',es:'Chat Hub',en:'Chat Hub'}
  ];
  const found=routes.find(r=>r.keys.some(k=>f.includes(k)));
  if(found)return reply(`Claro. Abre ${found.es}.`,`Sure. Open ${found.en}.`,{actions:[{id:`navigate:${found.target}`,labelEs:`Abrir ${found.es}`,labelEn:`Open ${found.en}`,kind:'navigate',target:found.target}]});
  if(isAdmin(req.identity)&&/admin|administracion|administrador|consola/.test(f))return reply('Claro. Abre la consola de administración.','Sure. Open the administration console.',{actions:[{id:'open-admin',labelEs:'Abrir Administración',labelEn:'Open Administration',kind:'url',url:'/admin/'}]});
  return reply('¿Qué sección quieres abrir: Inicio, Programa, Iglesia, Eventos, Tareas, Peticiones, Perfil o Cuidado de Niños?','Which section would you like to open: Home, Schedule, Church, Events, Tasks, Prayer Requests, Profile, or Children Care?');
}

