  return loc==='en'?reply('',`Regular services:\n${lines}`,{actions:[{id:'navigate:schedule',labelEs:'Ver programa',labelEn:'View schedule',kind:'navigate',target:'schedule'}]}):reply(`Servicios habituales:\n${lines}`,'',{actions:[{id:'navigate:schedule',labelEs:'Ver programa',labelEn:'View schedule',kind:'navigate',target:'schedule'}]});
