async function eventDismiss(req,message,state){
  const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},today=churchDateISO(settings.timezone||config.defaultTimezone),events=(await listDocs(tableNames.events,req.churchId,{max:2000})).filter(e=>e.active!==false&&String(e.dateISO||'')>=today),ranked=rankEvents(events,message);let choices=ranked.filter(x=>x.score>0).map(x=>x.e);if(!choices.length&&events.length===1)choices=events;
  if(!choices.length)return reply('No pude identificar el evento que quieres quitar. Dime el nombre.','I could not identify the event you want to hide. Tell me its name.');
  if(choices.length>1){state.pending={type:'event.dismiss.select',options:choices.slice(0,8).map(e=>({id:e.id,name:e.titleEs||e.titleEn}))};return reply('¿Cuál evento quieres quitar de tu pantalla?','Which event do you want to remove from your screen?',{pending:true,actions:state.pending.options.map(o=>({id:`event-dismiss:${o.id}`,labelEs:o.name,labelEn:o.name,kind:'reply'}))});}
  return dismissEventById(req,choices[0].id,state,true);
}
async function dismissEventById(req,eventId,state,confirm=false){const event=await getDoc(tableNames.events,req.churchId,eventId);if(!event)return reply('No encontré ese evento.','I could not find that event.');const title=event.titleEs||event.titleEn||'Evento';if(confirm){state.pending={type:'event.dismiss.confirm',eventId,title};return reply(`Voy a quitar “${title}” de tu pantalla. Tu RSVP y el historial del evento se conservarán en reportes. ¿Confirmas?`,`I will remove “${title}” from your screen. Your RSVP and event history will remain in reports. Confirm?`,{pending:true,actions:[{id:'event-dismiss:confirm',labelEs:'Sí, quitar',labelEn:'Yes, remove',kind:'reply'},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});}const id=`${event.id}__${req.identity.member.id}`,old=await getDoc(tableNames.eventRegistrations,req.churchId,id),doc={...(old||{}),id,eventId:event.id,memberId:req.identity.member.id,memberName:req.identity.member.fullName||'',status:old?.status||'dismissed',hiddenByMember:true,partySize:Number(old?.partySize||1),createdAt:old?.createdAt||nowIso(),updatedAt:nowIso()};await putDoc(tableNames.eventRegistrations,req.churchId,id,doc,{eventId:event.id,memberId:doc.memberId,status:doc.status});await appendHistory(req.churchId,{eventType:'event.hidden_by_member',memberId:doc.memberId,dateISO:event.dateISO||'',source:'chat-hub',details:{eventId:event.id,status:doc.status}});state.pending=null;return reply(`Listo. “${title}” ya no aparecerá en tu pantalla.`,`Done. “${title}” will no longer appear on your screen.`);}

async function taskActionStart(req,message,state,mode){
  const settings=await getDoc(tableNames.settings,req.churchId,'church')||{},today=churchDateISO(settings.timezone||config.defaultTimezone),rows=(await listDocs(tableNames.followUps,req.churchId,{filter:`assignedTo eq '${escApos(req.identity.member.id)}'`,max:1000})).filter(x=>x.hiddenByAssignee!==true&&(!x.dueDate||x.dueDate>=today));
  if(!rows.length)return reply('No tienes tareas visibles para modificar.','You have no visible tasks to change.');
  const terms=queryTerms(message),ranked=rows.map(x=>({x,score:matchContent({titleEs:x.title,bodyEs:x.notes},terms)})).sort((a,b)=>b.score-a.score);let choices=ranked.filter(x=>x.score>0).map(x=>x.x);if(!choices.length&&rows.length===1)choices=rows;
  const verb=mode==='cancel'?'cancelar':'quitar de tu pantalla';
  if(!choices.length||choices.length>1){const opts=(choices.length?choices:rows).slice(0,8);state.pending={type:`task.${mode}.select`,options:opts.map(x=>({id:x.id,name:x.title}))};return reply(`¿Cuál tarea quieres ${verb}?`,`${mode==='cancel'?'Which task do you want to cancel?':'Which task do you want to remove from your screen?'}`,{pending:true,actions:state.pending.options.map(o=>({id:`task-${mode}:${o.id}`,labelEs:o.name,labelEn:o.name,kind:'reply'}))});}
  return taskActionConfirm(req,choices[0],state,mode);
}
function taskActionConfirm(req,row,state,mode){state.pending={type:`task.${mode}.confirm`,taskId:row.id,title:row.title};return reply(mode==='cancel'?`Voy a cancelar “${row.title}”. Quedará registrada en reportes con estatus cancelado. ¿Confirmas?`:`Voy a quitar “${row.title}” de tu pantalla. Su estatus actual quedará registrado en reportes. ¿Confirmas?`,mode==='cancel'?`I will cancel “${row.title}”. It will remain in reports with cancelled status. Confirm?`:`I will remove “${row.title}” from your screen. Its current status will remain in reports. Confirm?`,{pending:true,actions:[{id:`task-${mode}:confirm`,labelEs:'Confirmar',labelEn:'Confirm',kind:'reply'},{id:'cancel',labelEs:'No hacer cambios',labelEn:'Do not change',kind:'reply'}]});}
async function saveTaskAction(req,state,mode){const p=state.pending,row=await getDoc(tableNames.followUps,req.churchId,p.taskId);if(!row||row.assignedTo!==req.identity.member.id){state.pending=null;return reply('No encontré esa tarea.','I could not find that task.');}if(mode==='cancel')row.status='cancelled';else{row.hiddenByAssignee=true;row.hiddenAt=nowIso();}row.updatedAt=nowIso();row.updatedBy=req.identity.member.id;await putDoc(tableNames.followUps,req.churchId,row.id,row,{status:row.status||'open',assignedTo:row.assignedTo||'',dueDate:row.dueDate||''});await appendHistory(req.churchId,{eventType:mode==='cancel'?'followup.member_updated':'followup.hidden_by_assignee',memberId:req.identity.member.id,source:'chat-hub',details:{followUpId:row.id,status:row.status||'open'}});state.pending=null;return reply(mode==='cancel'?`✅ Tarea cancelada: ${row.title}.`:`Listo. ${row.title} ya no aparecerá en tu pantalla.`,mode==='cancel'?`✅ Task cancelled: ${row.title}.`:`Done. ${row.title} will no longer appear on your screen.`);}

