async function handleAction(req,action,state){if(action==='cancel'){state.pending=null;return reply('Cancelado. No hice ningún cambio.','Cancelled. I did not make any changes.');}
  if(action?.startsWith('child-code:')){const id=action.split(':')[1],row=await getDoc(tableNames.childCheckIns,req.churchId,id);if(!row||row.memberId!==req.identity.member.id)return reply('No pude encontrar ese registro activo.','I could not find that active check-in.');state.pending=null;const r=await recoverOrRotatePickupCode(req.churchId,row,req.identity.member.id);return reply(`El código de recogida para ${row.childName} es ${r.code}.`,`The pickup code for ${row.childName} is ${r.code}.`,{sensitive:true});}
  if(action?.startsWith('child-pickup:')){const id=action.split(':')[1],row=await getDoc(tableNames.childCheckIns,req.churchId,id);if(!row||row.memberId!==req.identity.member.id)return reply('No pude encontrar ese registro activo.','I could not find that active check-in.');state.pending=null;return pickupRequest(req,row.childName,state);}
  if(action?.startsWith('replacement:')&&action!=='replacement:confirm'){const id=action.split(':')[1],a=await getDoc(tableNames.assignments,req.churchId,id);if(!a||a.currentMemberId!==req.identity.member.id)return reply('No encontré esa asignación activa en tu cuenta.','I could not find that active assignment on your account.');state.pending={type:'replacement.confirm',assignmentId:a.id,dateISO:a.dateISO,labelEs:a.assignmentKey,labelEn:a.assignmentKey};return replacementConfirmation(state.pending);}
  if(action==='replacement:confirm'&&state.pending?.type==='replacement.confirm'){const p=state.pending;state.pending=null;await requestReplacement(req.churchId,req.identity.member.id,p.assignmentId,{reason:'chat_hub'});return reply('Listo. La solicitud de reemplazo fue procesada.','Done. The replacement request was processed.');}
  if(action==='availability:confirm'&&state.pending?.type==='availability.confirm'){const p=state.pending;state.pending=null;const result=await addUnavailability(req.churchId,req.identity.member.id,{from:p.from,to:p.to,note:'Chat Hub'});return reply(`Listo. Registré tu ausencia del ${p.from} al ${p.to}.${result.affected?` Se procesaron ${result.affected} asignaciones afectadas.`:''}`,`Done. I recorded your unavailability from ${p.from} through ${p.to}.${result.affected?` ${result.affected} affected assignments were processed.`:''}`);}
  if(action?.startsWith('task-complete:')){if(action==='task-complete:confirm'&&state.pending?.type==='task.complete.confirm'){const p=state.pending,row=await getDoc(tableNames.followUps,req.churchId,p.taskId);if(!row||row.assignedTo!==req.identity.member.id)return reply('No encontré esa tarea.','I could not find that task.');row.status='completed';row.updatedAt=nowIso();row.updatedBy=req.identity.member.id;await putDoc(tableNames.followUps,req.churchId,row.id,row,{status:row.status,assignedTo:row.assignedTo||'',dueDate:row.dueDate||''});state.pending=null;return reply(`✅ Tarea completada: ${row.title}.`,`✅ Task completed: ${row.title}.`);}const id=action.split(':')[1],row=await getDoc(tableNames.followUps,req.churchId,id);if(!row||row.assignedTo!==req.identity.member.id)return reply('No encontré esa tarea.','I could not find that task.');state.pending={type:'task.complete.confirm',taskId:row.id,title:row.title};return reply(`Voy a marcar “${row.title}” como completada. ¿Confirmas?`,`I will mark “${row.title}” complete. Confirm?`,{pending:true,actions:[{id:'task-complete:confirm',labelEs:'Sí, completar',labelEn:'Yes, complete',kind:'reply'},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});}
  if(action?.startsWith('parent-verify:')){const id=action.split(':')[1],row=await getDoc(tableNames.childCheckIns,req.churchId,id);if(!row||row.memberId!==req.identity.member.id||!activeCheck(row))return reply('No encontré ese registro activo.','I could not find that active check-in.');state.pending=null;return issueParentVerification(req,row);}
  if(action?.startsWith('prayer-delete:')){const id=action.split(':')[1],row=await getDoc(tableNames.petitions,req.churchId,id);if(!row||row.memberId!==req.identity.member.id)return reply('Esa petición no está disponible para eliminar.','That prayer request is not available to delete.');state.pending={type:'prayer.delete.confirm',petitionId:id,text:row.text};return reply(`¿Eliminar permanentemente esta petición?\n“${row.text}”`,`Permanently delete this prayer request?\n“${row.text}”`,{pending:true,actions:[{id:'prayer:delete-confirm',labelEs:'Eliminar',labelEn:'Delete',kind:'reply',danger:true},{id:'cancel',labelEs:'Cancelar',labelEn:'Cancel',kind:'reply'}]});}
  if(action==='prayer:delete-confirm'&&state.pending?.type==='prayer.delete.confirm'){const row=await getDoc(tableNames.petitions,req.churchId,state.pending.petitionId);if(!row||row.memberId!==req.identity.member.id){state.pending=null;return reply('Esa petición ya no está disponible para eliminar.','That prayer request is no longer available to delete.');}await deleteDoc(tableNames.petitions,req.churchId,row.id);await appendHistory(req.churchId,{eventType:'petition.deleted_by_owner',memberId:req.identity.member.id,source:'chat-hub',details:{petitionId:row.id}});state.pending=null;return reply('✅ Petición eliminada permanentemente.','✅ Prayer request permanently deleted.');}
  if(action?.startsWith('event-dismiss:')){if(action==='event-dismiss:confirm'&&state.pending?.type==='event.dismiss.confirm')return dismissEventById(req,state.pending.eventId,state,false);const id=action.split(':')[1];return dismissEventById(req,id,state,true);}
  if(action?.startsWith('task-cancel:')){if(action==='task-cancel:confirm'&&state.pending?.type==='task.cancel.confirm')return saveTaskAction(req,state,'cancel');const id=action.split(':')[1],row=await getDoc(tableNames.followUps,req.churchId,id);if(!row||row.assignedTo!==req.identity.member.id)return reply('No encontré esa tarea.','I could not find that task.');return taskActionConfirm(req,row,state,'cancel');}
  if(action?.startsWith('task-dismiss:')){if(action==='task-dismiss:confirm'&&state.pending?.type==='task.dismiss.confirm')return saveTaskAction(req,state,'dismiss');const id=action.split(':')[1],row=await getDoc(tableNames.followUps,req.churchId,id);if(!row||row.assignedTo!==req.identity.member.id)return reply('No encontré esa tarea.','I could not find that task.');return taskActionConfirm(req,row,state,'dismiss');}
  if(action?.startsWith('rsvp-register:')){const e=await getDoc(tableNames.events,req.churchId,action.split(':')[1]);if(!e)return reply('No encontré ese evento.','I could not find that event.');return rsvpConfirm(req,e,state,false);}
  if(action?.startsWith('rsvp-cancel:')){const e=await getDoc(tableNames.events,req.churchId,action.split(':')[1]);if(!e)return reply('No encontré ese evento.','I could not find that event.');return rsvpConfirm(req,e,state,true);}
  if(action==='rsvp:register-confirm'&&state.pending?.type==='rsvp.register.confirm')return saveRsvp(req,state,false);
  if(action==='rsvp:cancel-confirm'&&state.pending?.type==='rsvp.cancel.confirm')return saveRsvp(req,state,true);
  if(action==='member:create-confirm'&&state.pending?.type==='member.create.confirm')return memberCreatePending(req,'',state,action);
  if(action==='schedule:generate-confirm'&&state.pending?.type==='schedule.generate.confirm'){const result=await generateThreeWeekSchedule(req.churchId,{source:'chat-hub-admin'});state.pending=null;return reply('✅ El programa de las próximas tres semanas fue generado.','✅ The next three weeks of schedules were generated.',{data:result,actions:[{id:'navigate:schedule',labelEs:'Ver programa',labelEn:'View schedule',kind:'navigate',target:'schedule'}]});}
  if(action==='module:toggle-confirm'&&state.pending?.type==='module.toggle.confirm'){const {updateModules}=await import('../modules/registry.js');const p=state.pending;const result=await updateModules(req.churchId,{[p.moduleId]:p.enabled},req.identity.member?.id||'');state.pending=null;return reply(`✅ ${p.labelEs} está ${p.enabled?'activo':'desactivado'}.`,`✅ ${p.labelEn} is ${p.enabled?'enabled':'disabled'}.`,{data:{modules:result}});}
  if(action?.startsWith('prayer:'))return prayerCreatePending(req,'',state,action);
  if(action?.startsWith('member:'))return memberCreatePending(req,'',state,action);
  if(action?.startsWith('announcement:'))return announcementCreatePending(req,'',state,action);
  if(action?.startsWith('event:'))return eventCreatePending(req,'',state,action);
  if(action?.startsWith('task:create'))return taskCreatePending(req,'',state,action);
  if(action?.startsWith('bulletin:'))return bulletinPending(req,'',null,state,action);
  return null;}

export async function executeIntent(req,{intent,message,attachment,state,action}){
  const ordinalAction=!action&&state.pending?pendingOrdinalAction(message,state):'';if(ordinalAction){const r=await handleAction(req,ordinalAction,state);if(r)return r;}
  if(action){const r=await handleAction(req,action,state);if(r)return r;}
  if(state.pending?.type?.startsWith('bulletin.'))return bulletinPending(req,message,attachment,state,action);
  if(state.pending?.type?.startsWith('announcement.create.'))return announcementCreatePending(req,message,state,action);
  if(state.pending?.type?.startsWith('event.create.'))return eventCreatePending(req,message,state,action);
  if(state.pending?.type?.startsWith('task.create.'))return taskCreatePending(req,message,state,action);
  if(state.pending?.type?.startsWith('prayer.create.'))return prayerCreatePending(req,message,state,action);
  if(state.pending?.type?.startsWith('member.create.'))return memberCreatePending(req,message,state,action);
  if(state.pending?.type?.startsWith('prayer.delete.')){if(isYes(message)&&state.pending.type==='prayer.delete.confirm')return handleAction(req,'prayer:delete-confirm',state);return prayerDeleteStart(req,state);}
  if(state.pending?.type==='schedule.generate.confirm'&&isYes(message))return handleAction(req,'schedule:generate-confirm',state);
  if(state.pending?.type==='module.toggle.confirm'&&isYes(message))return handleAction(req,'module:toggle-confirm',state);
  if(state.pending?.type==='rsvp.register.confirm'&&isYes(message))return handleAction(req,'rsvp:register-confirm',state);
  if(state.pending?.type==='rsvp.cancel.confirm'&&isYes(message))return handleAction(req,'rsvp:cancel-confirm',state);
  if(state.pending?.type==='event.dismiss.confirm'&&isYes(message))return handleAction(req,'event-dismiss:confirm',state);
  if(state.pending?.type==='task.cancel.confirm'&&isYes(message))return handleAction(req,'task-cancel:confirm',state);
  if(state.pending?.type==='task.dismiss.confirm'&&isYes(message))return handleAction(req,'task-dismiss:confirm',state);
  if(isCancel(message)&&state.pending){state.pending=null;return reply('Cancelado. No hice ningún cambio.','Cancelled. I did not make any changes.');}
  if(state.pending?.type==='replacement.confirm'&&isYes(message))return handleAction(req,'replacement:confirm',state);
  if(state.pending?.type==='availability.confirm'&&isYes(message))return handleAction(req,'availability:confirm',state);
  if(state.pending?.type==='task.complete.confirm'&&isYes(message))return handleAction(req,'task-complete:confirm',state);
  switch(intent){
    case 'help': return reply('Puedes preguntarme qué te toca, quién sirve o predica, programas, Cantos, reemplazos, ausencias, anuncios, eventos y RSVP, tareas, peticiones de oración y Cuidado de Niños. También puedo crear peticiones, registrar o cancelar RSVP, solicitar recogida y generar verificación alternativa para padres. Administradores: puedo buscar o crear miembros y cuentas, revisar todas las peticiones, generar el programa, ver Cantos pendientes, subir boletines, crear anuncios/eventos/tareas y consultar módulos. El Administrador principal también puede activar o desactivar módulos.','You can ask what you are assigned, who is serving or preaching, schedules, Songs, replacements, unavailability, announcements, events and RSVPs, tasks, prayer requests, and Children Care. I can also create prayer requests, register/cancel RSVP, request pickup, and generate alternate parent verification. Admins can search/create members and accounts, review all prayer requests, generate schedules, inspect missing songs, upload bulletins, create announcements/events/tasks, and check modules. The Church Administrator can also enable or disable modules.');
    case 'navigation.open': return navigationOpen(req,message);
    case 'hub.upcomingSummary': return upcomingSummary(req);
    case 'services.query': return servicesQuery(req);
    case 'assignments.mine': return assignmentsMine(req);
    case 'program.query': return programQuery(req,message);
    case 'profile.mine': return profileMine(req);
    case 'notifications.mine': return notificationsMine(req);
    case 'songs.search': return songsSearch(req,message);
    case 'songs.history': return songsHistory(req);
    case 'bulletins.latest': return latestBulletin(req);
    case 'announcements.count': return announcementsCount(req,message);
    case 'announcements.list': return announcementsList(req,message);
    case 'announcements.query': return announcementsQuery(req,message);
    case 'events.query': return eventsQuery(req,message);
    case 'events.myRsvp': return myRsvp(req);
    case 'events.register': return rsvpStart(req,message,state,{cancel:false});
    case 'events.cancelRsvp': return rsvpStart(req,message,state,{cancel:true});
    case 'events.dismiss': return eventDismiss(req,message,state);
    case 'tasks.mine': return tasksMine(req);
    case 'tasks.complete': return taskComplete(req,message,state);
    case 'tasks.cancel': return taskActionStart(req,message,state,'cancel');
    case 'tasks.dismiss': return taskActionStart(req,message,state,'dismiss');
    case 'prayer.list': return prayerList(req);
    case 'prayer.mine': return prayerMine(req);
    case 'prayer.create': return prayerCreateStart(state,message);
    case 'prayer.delete': return prayerDeleteStart(req,state);
    case 'prayer.deleteExpired': return prayerDeleteStart(req,state);
    case 'children.pickupCode': return pickupCode(req,message,state);
    case 'children.parentVerification': return parentVerification(req,message,state);
    case 'children.status': return childrenStatus(req);
    case 'children.pickupRequest': return pickupRequest(req,message,state);
    case 'children.workerStatus': return childrenWorkerStatus(req);
    case 'replacement.request': return replacement(req,message,state);
    case 'availability.add': return availability(req,message,state);
    case 'admin.console': return reply('Abre la consola de administración.','Open the administration console.',{actions:[{id:'open-admin',labelEs:'Abrir Administración',labelEn:'Open Administration',kind:'url',url:'/admin/'}]});
    case 'admin.programStatus': return programStatus(req);
    case 'admin.scheduleGenerate': return scheduleGenerateStart(state);
    case 'admin.pendingSongs': return pendingSongs(req);
    case 'admin.memberSearch': return memberSearch(req,message);
    case 'admin.memberCreate': return memberCreateStart(state);
    case 'admin.bulletinUpload': return bulletinStart(req,attachment,state);
    case 'admin.announcementCreate': return announcementCreateStart(state);
    case 'admin.eventCreate': return eventCreateStart(state);
    case 'admin.eventRsvpList': return eventRsvpList(req,message);
    case 'admin.visitors.query': return visitorsQuery(req);
    case 'admin.taskCreate': return taskCreateStart(state);
    case 'admin.tasks.query': return adminTasksQuery(req);
    case 'admin.prayer.list': return prayerAdminList(req);
    case 'admin.childrenStatus': return adminChildrenStatus(req);
    case 'admin.reports.query': return adminReportsQuery(req);
    case 'admin.communications.query': return adminCommunicationsQuery(req);
    case 'admin.audit.query': return adminAuditQuery(req);
    case 'admin.modules.query': return modulesQuery(req);
    case 'admin.moduleToggle': return moduleToggleStart(req,message,state);
    default: return null;
  }
}
